// === Tab: Main ===
let particle;
let num = 200;

function setup() {
	createCanvas(windowHeight*4/3, windowHeight);
	strokeWeight(1.3);
	colorMode(HSB);

	resetParticles();
}

function draw() {
	for (let i = 0; i < num; i++) {
		particle[i].draw();
		particle[i].update();i
	}
}

function resetParticles() {
	particle = [];
	background(0);
	for (let i = 0; i < num; i++) {
		particle[i] = new Particle(width / 2, height / 2, 0.01, 0.3, 0.03);
	}
}
